The provided solution defines an AVL node whose subtree_update computes subtree sum, maximum prefix sum, and a maximizing key; a tree wrapper exposing max_prefix; and then sorts toppings by x, inserts each (y,t) item, and keeps the best returned prefix:

class Part_B_Node(BST_Node):
    def subtree_update(A):
        super().subtree_update()
        A.sum = A.item.val
        if A.left:
            A.sum += A.left.sum
        if A.right:
            A.sum += A.right.sum
        left = -float('inf')
        right = -float('inf')
        middle = A.item.val
        if A.left:
            left = A.left.max_prefix
            middle += A.left.sum
        if A.right:
            right = middle + A.right.max_prefix
        A.max_prefix = max(left, middle, right)
        if left == A.max_prefix:
            A.max_prefix_key = A.left.max_prefix_key
        elif middle == A.max_prefix:
            A.max_prefix_key = A.item.key
        else:
            A.max_prefix_key = A.right.max_prefix_key

class Part_B_Tree(Set_AVL_Tree):
    def __init__(self):
        super().__init__(Part_B_Node)

    def max_prefix(self):
        k = self.root.max_prefix_key
        s = self.root.max_prefix
        return (k, s)

def tastiest_slice(toppings):
    B = Part_B_Tree()
    X, Y, T = 0, 0, 0
    toppings.sort(key=lambda topping: topping[0])
    for (x, y, t) in toppings:
        B.insert(Key_Val_Item(y, t))
        (Y_, T_) = B.max_prefix()
        if T < T_:
            X, Y, T = x, Y_, T_
    return (X, Y, T)

The implementation sorts once and performs one AVL insertion and O(1) max-prefix query per topping, for O(n log n) time.

The provided solution constructs an adjacency list and weight dictionary; adds a supernode n with zero-weight edges to all original vertices; runs Bellman-Ford from the supernode; returns None if Bellman-Ford detects a negative cycle; uses the returned potential h to reweight edges; runs Dijkstra from each original vertex; and converts reweighted distances back to original distances.

```python
INF = 99999 # distance magnitudes will not be larger than this number

def johnson(n, S):
    D = [[INF for _ in range(n)] for _ in range(n)]
    Adj = [[] for _ in range(n)] # construct graph
    W = {}
    for (u, v, w) in S:
        Adj[u].append(v)
        W[(u, v)] = w
    Adj.append([i for i in range(n)]) # run bellman-ford from supernode
    for i in range(n):
        W[(n, i)] = 0
    def wf(u, v): return W[(u, v)]
    args = bellman_ford(Adj, wf, n)
    if args is None:
        return None
    h, _ = args
    def wf(u, v): return W[(u, v)] + h[u] - h[v]
    for u in range(n): # compute SSSP on reweighted graph
        d, parent = dijkstra(Adj, wf, u)
        for v in range(n):
            if d[v] < INF:
                D[u][v] = d[v] - h[u] + h[v]
    return tuple(tuple(row) for row in D)
```

The provided code defines: (1) dijkstra(Adj,w,s), ordinary Dijkstra implemented with a direct-access list queue and linear scan for the minimum-distance queued vertex; (2) dijkstra_bottleneck(Adj,w,s), which instead initializes the source to infinity, extracts the maximum bottleneck estimate, and relaxes with max(d[v], min(d[u], w(u,v))); and (3) ship_server_stats(R,s,t). The function maps city names to integer indices, builds adjacency lists and dictionaries for capacity and cost, computes the maximum bottleneck w using dijkstra_bottleneck, assigns infinite cost to every edge whose capacity is less than w, runs ordinary dijkstra using the resulting costs, and returns (w,c), where c is the minimum cost to t.

Provided implementation:
```python
def dijkstra(Adj, w, s):
    d = [float('inf') for _ in Adj]
    d[s] = 0
    Q = [i for i in range(len(Adj))]
    while len(Q) > 0:
        u = Q[0]
        for v in Q:
            if d[v] < d[u]:
                u = v
        Q.remove(u)
        for v in Adj[u]:
            d[v] = min(d[v], d[u] + w(u, v))
    return d

def dijkstra_bottleneck(Adj, w, s):
    d = [0 for _ in Adj]
    d[s] = float('inf')
    Q = [i for i in range(len(Adj))]
    while len(Q) > 0:
        u = Q[0]
        for v in Q:
            if d[v] > d[u]:
                u = v
        Q.remove(u)
        for v in Adj[u]:
            d[v] = max(d[v], min(d[u], w(u, v)))
    return d

def ship_server_stats(R, s, t):
    n = 0
    city_idx = {}
    for (_s, _t, _w, _c) in R:
        for city in (_s, _t):
            if city not in city_idx:
                city_idx[city] = n
                n += 1
    Adj = [[] for i in range(n)]
    w_w, w_c = {}, {}
    for (_s, _t, _w, _c) in R:
        si, ti = city_idx[_s], city_idx[_t]
        Adj[si].append(ti)
        w_w[(si, ti)], w_c[(si, ti)] = _w, _c
    si, ti = city_idx[s], city_idx[t]
    w = dijkstra_bottleneck(Adj, lambda u, v: w_w[(u, v)], si)[ti]
    for i in range(n):
        for j in Adj[i]:
            if w_w[(i, j)] < w:
                w_c[(i, j)] = float('inf')
    c = dijkstra(Adj, lambda u, v: w_c[(u, v)], si)[ti]
    return w, c
```
